create table if not exists public.customer_notification_preferences(id uuid primary key default gen_random_uuid(),tenant_id uuid not null references public.tenants(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,transactional_email boolean not null default true,transactional_sms boolean not null default true,transactional_whatsapp boolean not null default false,transactional_push boolean not null default false,marketing_email boolean not null default false,marketing_sms boolean not null default false,marketing_whatsapp boolean not null default false,marketing_push boolean not null default false,updated_at timestamptz not null default now(),unique(tenant_id,user_id));
create table if not exists public.customer_notification_consent_log(id bigint generated always as identity primary key,tenant_id uuid not null references public.tenants(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,preference_key text not null,new_value boolean not null,source text not null default 'account',created_at timestamptz not null default now());
alter table public.customer_notification_preferences enable row level security;alter table public.customer_notification_consent_log enable row level security;
create policy customer_notification_preferences_self on public.customer_notification_preferences for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());create policy customer_notification_consent_log_self_read on public.customer_notification_consent_log for select to authenticated using(user_id=auth.uid());
create or replace function public.save_customer_notification_preferences(p_tenant uuid,p_values jsonb) returns void language plpgsql security definer set search_path=public as $$declare k text;oldv boolean;newv boolean;allowed text[]:=array['transactional_email','transactional_sms','transactional_whatsapp','transactional_push','marketing_email','marketing_sms','marketing_whatsapp','marketing_push'];begin if auth.uid() is null then raise exception 'authentication_required';end if;if not exists(select 1 from public.customer_profiles where tenant_id=p_tenant and user_id=auth.uid()) then raise exception 'customer_profile_required';end if;insert into public.customer_notification_preferences(tenant_id,user_id) values(p_tenant,auth.uid()) on conflict(tenant_id,user_id) do nothing;foreach k in array allowed loop if p_values ? k then newv=(p_values->>k)::boolean;execute format('select %I from public.customer_notification_preferences where tenant_id=$1 and user_id=$2',k) into oldv using p_tenant,auth.uid();if oldv is distinct from newv then execute format('update public.customer_notification_preferences set %I=$1,updated_at=now() where tenant_id=$2 and user_id=$3',k) using newv,p_tenant,auth.uid();insert into public.customer_notification_consent_log(tenant_id,user_id,preference_key,new_value) values(p_tenant,auth.uid(),k,newv);end if;end if;end loop;end$$;revoke all on function public.save_customer_notification_preferences(uuid,jsonb) from public;grant execute on function public.save_customer_notification_preferences(uuid,jsonb) to authenticated;
insert into public.admin_help_items(help_key,title_fa,body_fa,warning_fa,title_en,body_en,warning_en,active) values('customers.notifications','ترجیحات اعلان مشتری','مشتری می‌تواند کانال‌های اعلان تراکنشی و بازاریابی را جداگانه مدیریت کند. تغییر رضایت بازاریابی در دفترچه Consent ثبت می‌شود تا سابقه قابل پیگیری باشد.','پیام‌های ضروری امنیتی یا قانونی نباید به تنظیمات بازاریابی وابسته شوند. رضایت تبلیغاتی پیش‌فرض خاموش است و نباید بدون اقدام صریح مشتری روشن شود.','Customer notification preferences','Customers can independently manage transactional and marketing notification channels. Consent changes are recorded in a consent ledger for traceability.','Security or legally required notices must not depend on marketing preferences. Marketing consent defaults to off and must not be enabled without explicit customer action.',true) on conflict(help_key) do update set title_fa=excluded.title_fa,body_fa=excluded.body_fa,warning_fa=excluded.warning_fa,title_en=excluded.title_en,body_en=excluded.body_en,warning_en=excluded.warning_en,active=true;
